`timescale 1ns / 1ps

module tb_md5_single_block;

    reg clk;
    reg reset;
    reg [511:0] chunk;
    wire [31:0] a64, b64, c64, d64;

    Md5Core u_md5 (
        .clk(clk),
        .wb(chunk),
        .a0(32'h67452301),
        .b0(32'hefcdab89),
        .c0(32'h98badcfe),
        .d0(32'h10325476),
        .a64(a64),
        .b64(b64),
        .c64(c64),
        .d64(d64)
    );

    initial clk = 0;
    always #5 clk = ~clk;  // 100MHz

    initial begin
        $dumpfile("md5_single_block.vcd");
        $dumpvars(0, tb_md5_single_block);

        reset = 1;
        chunk = 512'b0;
        #20;
        reset = 0;
        #10;

        // "Hello World" padded message (same as test case 3)
        chunk = 512';

        // Wait for computation (65 cycles)
        #2000;

        $finish;
    end

endmodule